mapper.select:
SELECT c.*
FROM ecom_competitor_price c
WHERE c.listing_id IN #{id}
  AND c.snapshot_time >= #{since}
  AND c.id = (SELECT MAX(x.id) FROM ecom_competitor_price x WHERE x.listing_id = c.listing_id
              AND x.snapshot_time = (SELECT MAX(y.snapshot_time) FROM ecom_competitor_price y WHERE y.listing_id = c.listing_id))
